 "content": "def transform(grid):
    # Extract the 9-by-3 block immediately beside the marked region and rotate it clockwise.
    R,C=len(grid),len(grid[0])
    cells=[(r,c) for r in range(R) for c in range(C) if grid[r][c]==8]
    r0,r1=min(r for r,c in cells),max(r for r,c in cells)
    c0,c1=min(c for r,c in cells),max(c for r,c in cells)
    h,w=r1-r0+1,c1-c0+1
    if c0==0:
        patch=[row[c1+1:c1+1+w] for row in grid[r0:r1+1]]
    elif c1==C-1:
        patch=[row[c0-w:c0] for row in grid[r0:r1+1]]
    elif r0==0:
        patch=[grid[r1+1+i][c0:c1+1] for i in range(h)]
    else:
        patch=[grid[r0+i][c0:c1+1] for i in range(h)]
    return [list(row) for row in zip(*patch[::-1])]
